static int flush_dir(const char *path)
{
	DIR *dir;
	struct dirent *de;
	int ret = 0;

	dir = opendir(path);
	if (!dir)
		return errno == ENOENT ? 0 : -1;
	while ((de = readdir(dir))) {
		char child[strlen(path) + strlen(de->d_name) + 2];
		sprintf(child, "%s/%s", path, de->d_name);
		if (de->d_name[0] == '.')
			continue;
		/* decide file or dir: stat */
		struct stat st;
		if (stat(child, &st))
			continue;
		if (S_ISDIR(st.st_mode)) {
			if (flush_dir(child))
				ret = -1;
		} else if (S_ISREG(st.st_mode)) {
			int fd = open(child, O_RDONLY);
			if (fd >= 0) {
				if (fsync(fd))
					ret = -1;
				close(fd);
			}
		}
