static ssize_t treeexpread(off_t a, char *buf, size_t len, CLIENT *client) {
	off_t foffset = a % TREEPAGESIZE;
	size_t chunk = TREEPAGESIZE - foffset;
	ssize_t retval;
	int fd;

	if (len > chunk)
		len = chunk;

	DEBUG("(TREAD from %llu len %u), ", (unsigned long long)a, (unsigned int)len);

	fd = open_treefile(client->exportname, O_RDONLY,
			   client->exportsize, a, &treefiles_lock);
	if(fd < 0) {
		if(errno == ENOENT) {
			/* the block has never been written, so it reads
			 * as all zeroes */
			memset(buf, 0, len);
			return len;
		}
		return -1;
	}
	retval = pread(fd, buf, len, foffset);
	if(retval >= 0 && (size_t)retval < len) {
		/* the block file is shorter than the read (e.g. a
		 * partial write at the end of the export); the hole
		 * reads as zeroes */
		memset(buf + retval, 0, len - retval);
		retval = len;
	}
	close(fd);
	return retval;
}

