Implementation:

```c
static GHashTable *dirty_files;
static pthread_mutex_t dirty_lock = PTHREAD_MUTEX_INITIALIZER;

void dirty_treefile(char *name, off_t size, off_t pos) {
	char path[strlen(name) + TREEPATH_EXTRA];

	strcpy(path, name);
	construct_path(path, sizeof(path), size, pos, NULL);
	pthread_mutex_lock(&dirty_lock);
	if (!dirty_files)
		dirty_files = g_hash_table_new_full(g_str_hash, g_str_equal, g_free, NULL);
	/* g_hash_table_add takes ownership of the key on insertion;
	 * if an equal key already exists, the new key replaces (and
	 * frees) it, so no leak */
	if (!g_hash_table_contains(dirty_files, path))
		g_hash_table_add(dirty_files, g_strdup(path));
	pthread_mutex_unlock(&dirty_lock);
}
```

Simpler: `g_hash_table_add` handles replacement — it takes ownership of the passed key; if an equal key exists, the old key is destroyed and the new key takes its place (in fact g_hash_table_add replaces the key too — the docs say "if a matching key already exists, the old key and value are replaced"). So simply: g_hash_table_add(dirty_files, g_strdup(path)). No problem.

delete_treefile: after unlink succeeds (or even on ENOENT — to cover the case where the file was deleted but the dirty entry remains), remove the path from dirty:

```c
	pthread_mutex_lock(&dirty_lock);
	if (dirty_files)
		g_hash_table_remove(dirty_files, path);
	pthread_mutex_unlock(&dirty_lock);
```

flush_dirty_treefiles:

```c
int flush_dirty_treefiles(void) {
	GHashTable *files;
	GHashTableIter iter;
	gpointer key;
	int ret = 0;

	pthread_mutex_lock(&dirty_lock);
	files = dirty_files;
	dirty_files = NULL;
	pthread_mutex_unlock(&dirty_lock);

	if (!files)
		return 0;

	g_hash_table_iter_init(&iter, files);
	while (g_hash_table_iter_next(&iter, &key, NULL)) {
		int fd = open(key, O_RDONLY);

		if (fd >= 0) {
			if (fsync(fd) < 0)
				ret = -1;
			close(fd);
		} else if (errno != ENOENT) {
			ret = -1;
		}
	}
	g_hash_table_destroy(files);
	return ret;
}
```

