/**
 * Recursively fsync all block files below a treefiles root directory,
 * so that a flush request gets the data of a treefiles export onto
 * stable storage.
 *
 * @param path the directory to flush
 * @return 0 on success, -1 on failure
 **/
static int flush_tree_dir(const char *path) {
	DIR *dir;
	struct dirent *de;
	int ret = 0;

	dir = opendir(path);
	if (!dir)
		return errno == ENOENT ? 0 : -1;
	while ((de = readdir(dir))) {
		char child[strlen(path) + strlen(de->d_name) + 2];
		struct stat st;

		if (de->d_name[0] == '.')
			continue;
		sprintf(child, "%s/%s", path, de->d_name);
		if (stat(child, &st) < 0)
			continue;
		if (S_ISDIR(st.st_mode)) {
			if (flush_tree_dir(child) < 0)
				ret = -1;
		} else if (S_ISREG(st.st_mode)) {
			int fd = open(child, O_RDONLY);

			if (fd >= 0) {
				if (fsync(fd) < 0)
					ret = -1;
				close(fd);
			} else {
				ret = -1;
			}
		}
	}
	closedir(dir);
	return ret;
}

int flush_treefiles(char *name) {
	return flush_tree_dir(name);
}

