/*
 * Tree files support for nbd-server.
 *
 * An export configured with "treefiles" is not backed by a single
 * large file. Instead, the data is stored in a tree of small block
 * files of TREEPAGESIZE bytes each, with at most TREEDIRSIZE files
 * or subdirectories per directory:
 *
 *	<exportname>/TREE0000/.../TREE0000/FILE0000
 *
 * The number of directory levels is chosen so that the tree can hold
 * exactly the number of bytes configured through the filesize option.
 * Block files (and the directories containing them) are created on
 * demand when data is written to them, and a block file is removed
 * again when the block is trimmed. Blocks without a file read as all
 * zeroes.
 */

#include "config.h"
#include "lfs.h"

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#include <glib.h>
#include <sys/stat.h>
#include <sys/types.h>

#include "treefiles.h"
#include "nbd-debug.h"

/* paths of block files that have received data since the last flush */
static GHashTable *dirty_files;
static pthread_mutex_t dirty_lock = PTHREAD_MUTEX_INITIALIZER;

/**
 * Compute the number of directory levels needed to hold an export of
 * the given size, i.e. the smallest depth d >= 1 for which
 * TREEDIRSIZE^d blocks of TREEPAGESIZE bytes can hold size bytes.
 *
 * @param size the size of the export in bytes
 * @return the depth of the tree
 **/
static int treedepth(off_t size) {
	int depth = 1;
	unsigned long long capacity = (unsigned long long)TREEDIRSIZE * TREEPAGESIZE;

	while (capacity < (unsigned long long)size) {
		depth++;
		/* one more level than can be spelled out covers any
		 * size expressible in an off_t, so stop multiplying */
		if (capacity > ULLONG_MAX / TREEDIRSIZE)
			break;
		capacity *= TREEDIRSIZE;
	}
	return depth;
}

void construct_path(char *name, int lenmax, off_t size, off_t pos, off_t *ppos) {
	int depth = treedepth(size);
	off_t block = pos / TREEPAGESIZE;
	off_t divisor = 1;
	int len = strlen(name);
	int i;

	for (i = 0; i < depth - 1; i++)
		divisor *= TREEDIRSIZE;

	for (i = depth - 1; i >= 0; i--) {
		int digit = (block / divisor) % TREEDIRSIZE;

		if (len < lenmax)
			len += snprintf(name + len, lenmax - len,
					i ? "/TREE%04d" : "/FILE%04d", digit);
		block %= divisor;
		divisor /= TREEDIRSIZE;
	}
	DEBUG("constructed path %s for position %llu\n", name,
	      (unsigned long long)pos);
	if (ppos)
		*ppos = pos % TREEPAGESIZE;
}

void mkdir_path(char *path) {
	char buf[strlen(path) + 1];
	char *p;

	strcpy(buf, path);
	for (p = buf + 1; *p; p++) {
		if (*p == '/') {
			*p = '\0';
			/* the directory may exist already, either because
			 * we raced another writer or because an earlier
			 * request created it */
			mkdir(buf, 0700);
			*p = '/';
		}
	}
	mkdir(buf, 0700);
}

int open_treefile(char *name, mode_t mode, off_t size, off_t pos, pthread_mutex_t *mutex) {
	char path[strlen(name) + TREEPATH_EXTRA];
	char *slash;
	int fd;

	strcpy(path, name);
	construct_path(path, sizeof(path), size, pos, NULL);

	if ((mode & O_ACCMODE) == O_RDONLY)
		return open(path, mode);

	pthread_mutex_lock(mutex);
	/* create the directories leading up to the block file, then the
	 * file itself. Both may exist already if another request got
	 * here first; mkdir_path() and open() don't mind. */
	slash = strrchr(path, '/');
	if (slash) {
		*slash = '\0';
		mkdir_path(path);
		*slash = '/';
	}
	fd = open(path, mode, 0600);
	pthread_mutex_unlock(mutex);
	return fd;
}

void delete_treefile(char *name, off_t size, off_t pos) {
	char path[strlen(name) + TREEPATH_EXTRA];

	strcpy(path, name);
	construct_path(path, sizeof(path), size, pos, NULL);
	pthread_mutex_lock(&dirty_lock);
	if (dirty_files)
		g_hash_table_remove(dirty_files, path);
	pthread_mutex_unlock(&dirty_lock);
	if (unlink(path) < 0 && errno != ENOENT) {
		DEBUG("could not delete treefile %s: %s\n", path,
		      strerror(errno));
	}
}

void dirty_treefile(char *name, off_t size, off_t pos) {
	char path[strlen(name) + TREEPATH_EXTRA];

	strcpy(path, name);
	construct_path(path, sizeof(path), size, pos, NULL);
	pthread_mutex_lock(&dirty_lock);
	if (!dirty_files)
		dirty_files = g_hash_table_new_full(g_str_hash, g_str_equal,
						    g_free, NULL);
	g_hash_table_add(dirty_files, g_strdup(path));
	pthread_mutex_unlock(&dirty_lock);
}

int flush_dirty_treefiles(void) {
	GHashTable *files;
	GHashTableIter iter;
	gpointer key;
	int ret = 0;

	pthread_mutex_lock(&dirty_lock);
	files = dirty_files;
	dirty_files = NULL;
	pthread_mutex_unlock(&dirty_lock);

	if (!files)
		return 0;

	g_hash_table_iter_init(&iter, files);
	while (g_hash_table_iter_next(&iter, &key, NULL)) {
		int fd = open(key, O_RDONLY);

		if (fd >= 0) {
			if (fsync(fd) < 0)
				ret = -1;
			close(fd);
		} else if (errno != ENOENT) {
			/* the file may have been trimmed again since it
			 * was dirtied; anything else is an error */
			ret = -1;
		}
	}
	g_hash_table_destroy(files);
	return ret;
}

