```c
#include <lfs.h>
#include <string.h>
#include <nbdsrv.h>  // hmm, not needed
#include "treefiles.h"
#include "macro.h"

int main(void) {
	char buf[256];
	off_t ppos;

	/* 4 MiB: 1024 blocks fit in one directory level */
	strcpy(buf, "export");
	construct_path(buf, sizeof buf, 4*1024*1024, 0, &ppos);
	count_assert(!strcmp(buf, "export/FILE0000"));
	count_assert(ppos == 0);

	strcpy(buf, "export");
	construct_path(buf, sizeof buf, 4*1024*1024, 4096*1023 + 100, &ppos);
	count_assert(!strcmp(buf, "export/FILE1023"));
	count_assert(ppos == 100);

	/* 8 MiB: 2048 blocks need two levels */
	strcpy(buf, "export");
	construct_path(buf, sizeof buf, 8*1024*1024, 4096, &ppos);
	count_assert(!strcmp(buf, "export/TREE0000/FILE0001"));

	strcpy(buf, "export");
	construct_path(buf, sizeof buf, 8*1024*1024, 8*1024*1024 - 1, &ppos);
	count_assert(!strcmp(buf, "export/TREE0001/FILE1023"));
	count_assert(ppos == 4095);

	/* 4 GiB: 1048576 blocks need two levels of directories */
	strcpy(buf, "export");
	construct_path(buf, sizeof buf, 4LL*1024*1024*1024, 4096LL*1024*1025, &ppos);
	count_assert(!strcmp(buf, "export/TREE0001/FILE0001"));

	/* 4 TiB needs three levels */
	strcpy(buf, "export");
	construct_path(buf, sizeof buf, 4LL*1024*1024*1024*1024, 4096LL*1024*1024*1025, &ppos);
	count_assert(!strcmp(buf, "export/TREE0001/TREE0000/FILE0001"));

	return 0;
}
```

Let me verify the calculations:
- 4 GiB export: number of blocks = 4 GiB/4 KiB = 1048576 = 1024^2 → depth 2. Block 1025 → digit: 1025 = 1*1024 + 1 → TREE0001/FILE0001. Offset = block*4096 = 1025*4096. ✓
- 4 TiB: blocks = 4 TiB / 4 KiB = 1073741824 = 1024^3 → depth 3. Block = 1024^2 + 1 → digit (from most significant): 1, 0, 1 → TREE0001/TREE0000/FILE0001. Offset = (1024*1024+1)*4096 = 4096*1024*1024 + 4096 → in my expression: 4096LL*1024*1024*1025 = 4096*1048576*1025?? No wait: 4096*1024*1024*1025 = 4096 * 1074790400... let me recompute: block = 1024*1024 + 1 = 1048577. pos = 1048577 * 4096. And 1048577 = 1024*1024 + 1, so pos = 4096*(1024*1024+1) = 4096*1024*1024 + 4096. My expression `4096LL*1024*1024*1025` = 4096*1048576*1025 = wrong! I need 4096LL*(1024*1024+1). Let me write it as (1024LL*1024+1)*4096.

