	strcpy(buf, "export");
	construct_path(buf, sizeof buf, 4LL * 1024 * 1024 * 1024, (1024LL * 1024 + 1) * 4096, &ppos);
	count_assert(!strcmp(buf, "export/TREE0001/FILE0001"));

