	count_assert(errno == ENOENT);

	fd = open_treefile(name, O_RDWR | O_CREAT, size, pos, &lock);
	count_assert(fd >= 0);
	count_assert(pwrite(fd, "x", 1, TREEPAGESIZE - 1) == 1);
	close(fd);

	strcpy(buf, name);
	construct_path(buf, sizeof buf, size, pos, &ppos);
	count_assert(ppos == TREEPAGESIZE - 1);
	count_assert(!strcmp(buf + strlen(buf) - 24,
